import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"第十三卦 同人 天火同人 乾上離下","description":"周易 - 第十三卦 同人 天火同人 乾上離下","frontmatter":{"title":"第十三卦 同人 天火同人 乾上離下","description":"周易 - 第十三卦 同人 天火同人 乾上離下"},"headers":[],"relativePath":"classics/zhouyi/014.md","filePath":"classics/zhouyi/014.md"}'),l={name:"classics/zhouyi/014.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="同人" tabindex="-1">同人 <a class="header-anchor" href="#同人" aria-label="Permalink to “同人”">​</a></h1><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>同人於野，亨。利涉大川，利君子貞。</p><h3 id="彖傳" tabindex="-1">彖傳 <a class="header-anchor" href="#彖傳" aria-label="Permalink to “彖傳”">​</a></h3><p>同人，柔得位得中，而應乎乾，曰同人。同人曰，同人於野，亨。利涉大川，乾行也。文明以健，中正而應，君子正也。唯君子為能通天下之志。</p><h3 id="象傳" tabindex="-1">象傳 <a class="header-anchor" href="#象傳" aria-label="Permalink to “象傳”">​</a></h3><p>天與火，同人；君子以類族辨物。</p><h3 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h3><p>同人於門，無咎。象曰：出門同人，又 誰咎也。</p><h3 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h3><p>同人於宗，吝。象曰：同人於宗，吝道也。</p><h3 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h3><p>伏戎於莽，升其高陵，三歲不興。象曰：伏戎於莽，敵剛也。三歲不興，安行也。</p><h3 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h3><p>乘其墉，弗克攻，吉。象曰：乘其墉，義弗克也，其吉，則困而反則也。</p><h3 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h3><p>同人，先號啕而後笑。大師克相遇。象曰：同人之先，以中直也。大師相遇，言相剋也。</p><h3 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h3><p>同人於郊，無悔。象曰：同人於郊，志未得也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
